                api.iset_x(p22, (api.iget_x(p22) + 8.0));
            }
        } else if (rt.eq(self.vars[g.VAR_facing], self.vars[g.VAR_RIGHT])) {
            if (rt.truthy(rt.ivar(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_heavy))) {
                rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_xVel, (4.0 + self.vars[g.VAR_xVel]));
            } else {
                rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_xVel, (8.0 + self.vars[g.VAR_xVel]));
            }
            if (rt.truthy(api.collision_point(self, other, (api.iget_x(self) + 8.0), api.iget_y(self), k.OBJ_oSolid, 0.0, 0.0))) {
                const p23 = rt.deref(self.vars[g.VAR_holdItem], self, other);
                api.iset_x(p23, (api.iget_x(p23) - 8.0));
            }
        }
        if (rt.truthy(rt.ivar(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_heavy))) {
            rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, (-2.0));
        } else {
            rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, (-3.0));
        }
        if (rt.truthy(self.vars[g.VAR_kUp])) {
            if (rt.truthy(rt.ivar(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_heavy))) {
                rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, (-4.0));
            } else {
                rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, (-9.0));
            }
        }
        if (rt.truthy(self.vars[g.VAR_kDown])) {
            if (rt.truthy(g.gml_script_platformCharacterIs(self, other, self.vars[g.VAR_ON_GROUND]))) {
                const p24 = rt.deref(self.vars[g.VAR_holdItem], self, other);
                api.iset_y(p24, (api.iget_y(p24) - 2.0));
                const p25 = rt.deref(self.vars[g.VAR_holdItem], self, other);
                rt.ivarSet(p25, g.VAR_xVel, (rt.ivar(p25, g.VAR_xVel) * 0.6));
                rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, 0.5);
            } else {
                rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, 3.0);
            }
        } else if (!rt.truthy(g.globals.hasMitt)) {
            if (rt.eq(self.vars[g.VAR_facing], self.vars[g.VAR_LEFT])) {
                if (rt.truthy(api.collision_point(self, other, (api.iget_x(self) - 8.0), (api.iget_y(self) - 10.0), k.OBJ_oSolid, 0.0, 0.0))) {
                    rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, 0.0);
                    const p26 = rt.deref(self.vars[g.VAR_holdItem], self, other);
                    rt.ivarSet(p26, g.VAR_xVel, (rt.ivar(p26, g.VAR_xVel) - 1.0));
                }
            } else if (rt.eq(self.vars[g.VAR_facing], self.vars[g.VAR_RIGHT])) {
                if (rt.truthy(api.collision_point(self, other, (api.iget_x(self) + 8.0), (api.iget_y(self) - 10.0), k.OBJ_oSolid, 0.0, 0.0))) {
                    rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, 0.0);
                    const p27 = rt.deref(self.vars[g.VAR_holdItem], self, other);
                    rt.ivarSet(p27, g.VAR_xVel, (rt.ivar(p27, g.VAR_xVel) + 1.0));
                }
            }
        }
        if ((rt.truthy(g.globals.hasMitt) and !rt.truthy(g.gml_script_scrPlayerIsDucking(self, other)))) {
            if (rt.lt(rt.ivar(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_xVel), 0.0)) {
                const p28 = rt.deref(self.vars[g.VAR_holdItem], self, other);
                rt.ivarSet(p28, g.VAR_xVel, (rt.ivar(p28, g.VAR_xVel) - 6.0));
            } else {
                const p29 = rt.deref(self.vars[g.VAR_holdItem], self, other);
                rt.ivarSet(p29, g.VAR_xVel, (rt.ivar(p29, g.VAR_xVel) + 6.0));
            }
            if ((!rt.truthy(self.vars[g.VAR_kUp]) and !rt.truthy(self.vars[g.VAR_kDown]))) {
                rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, (-0.4));
            } else if (rt.truthy(self.vars[g.VAR_kDown])) {
                rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_yVel, 6.0);
            }
            rt.ivarSet(rt.deref(self.vars[g.VAR_holdItem], self, other), g.VAR_myGrav, 0.1);
        }
        if (rt.eq(api.iget_sprite_index(rt.deref(self.vars[g.VAR_holdItem], self, other)), k.SPR_sBombArmed)) {
            g.gml_script_scrHoldItem(self, other, self.strs[g.SVAR_pickupItemType]);
        } else {
            self.vars[g.VAR_holdItem] = 0.0;
        }
        g.gml_script_playSound(self, other, g.globals.sndThrow);
    }
    if ((rt.truthy(self.vars[g.VAR_kDown]) and rt.truthy(self.vars[g.VAR_holdItem]))) {
        api.iset_x(rt.deref(self.vars[g.VAR_holdItem], self, other), api.iget_x(self));
        api.iset_y(rt.deref(self.vars[g.VAR_holdItem], self, other), api.iget_y(self));
    }
    if (rt.eq(self.vars[g.VAR_holdItem], 0.0)) {
        sm().assignStatic(&self.strs[g.SVAR_pickupItemType], "");
    }
}
